import sun.reflect.Reflection; // Note: In real projects, use ReflectionTestUtils or standard Reflection

public class FastDateFormat_applyRules_TriageGen0Test {

    /**
     * Since applyRules is protected and mRules is a private field, 
     * we use reflection to inject mocks into the FastDateFormat instance.
     */
    private FastDateFormat createInstanceWithMockRules(Rule[] mockRules) throws Exception {
        // Using a standard pattern to instantiate
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");

        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, mockRules);

        return fdf;
    }

    @Test
    public void testApplyRules_Success() throws Exception {
        // Arrange
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("Initial");

        // Create mock rules
        Rule rule1 = mock(Rule.class);
        Rule rule2 = mock(Rule.class);

        // Setup rule1 to append "Rule1"
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(InvocationOnMock invocation) {
                StringBuffer b = invocation.getArgument(0);
                Calendar c = invocation.getArgument(1);
                b.append("Rule1");
                return null;
            }
        }).when(rule1).appendTo(any(StringBuffer.class), any(Calendar.class));

        // Setup rule2 to append "Rule2"
        doAnswer(new Answer<Void>() {
            @Override
            public Void answer(InvocationOnMock invocation) {
                StringBuffer b = invocation.getArgument(0);
                Calendar c = invocation.getArgument(1);
                b.append("Rule2");
                return null;
            }
        }).when(rule2).appendTo(any(StringBuffer.class), any(Calendar.class));

        Rule[] mockRules = new Rule[]{rule1, rule2};
        FastDateFormat fdf = createInstanceWithMockRules(mockRules);

        // Act
        // Using reflection to call the protected method
        java.lang.reflect.Method method = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        method.setAccessible(true);
        StringBuffer result = (StringBuffer) method.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("InitialRule1Rule2", result.toString());
        assertSame(buf, result); // Should return the same buffer instance
        verify(rule1, times(1)).appendTo(buf, calendar);
        verify(rule2, times(1)).appendTo(buf, calendar);
    }

    @Test
    public void testApplyRules_EmptyRules() throws Exception {
        // Arrange
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("NoChange");
        Rule[] mockRules = new Rule[0];
        FastDateFormat fdf = createInstanceWithMockRules(mockRules);

        // Act
        java.lang.reflect.Method method = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        method.setAccessible(true);
        StringBuffer result = (StringBuffer) method.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("NoChange", result.toString());
        assertSame(buf, result);
    }

    @Test(expected = Exception.class)
    public void testApplyRules_NullRulesThrowsException() throws Exception {
        // Arrange
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer();
        // Inject null for mRules to test the loop boundary/null pointer logic
        FastDateFormat fdf = FastDateFormat.getInstance();
        Field rulesField = FastDateFormat.class.getDeclaredField("mRules");
        rulesField.setAccessible(true);
        rulesField.set(fdf, null);

        // Act
        java.lang.reflect.Method method = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        method.setAccessible(true);
        method.invoke(fdf, calendar, buf);

        // Assert - Exception expected
    }

    @Test
    public void testApplyRules_SingleRule() throws Exception {
        // Arrange
        Calendar calendar = Calendar.getInstance();
        StringBuffer buf = new StringBuffer("");
        Rule rule = mock(Rule.class);
        doAnswer(invocation -> {
            ((StringBuffer)invocation.getArgument(0)).append("Done");
            return null;
        }).when(rule).appendTo(any(StringBuffer.class), any(Calendar.class));

        Rule[] mockRules = new Rule[]{rule};
        FastDateFormat fdf = createInstanceWithMockRules(mockRules);

        // Act
        java.lang.reflect.Method method = FastDateFormat.class.getDeclaredMethod("applyRules", Calendar.class, StringBuffer.class);
        method.setAccessible(true);
        StringBuffer result = (StringBuffer) method.invoke(fdf, calendar, buf);

        // Assert
        assertEquals("Done", result.toString());
        verify(rule, times(1)).appendTo(buf, calendar);
    }
}
